using Ginecologia.Modules.Promociones.Domain;
using Microsoft.EntityFrameworkCore;
namespace Ginecologia.Modules.Promociones.Infrastructure;
public sealed class PromocionesDbContext(DbContextOptions<PromocionesDbContext> options) : DbContext(options)
{ public DbSet<Promotion> Promotions => Set<Promotion>(); protected override void OnModelCreating(ModelBuilder modelBuilder) { modelBuilder.HasDefaultSchema("promociones"); var promotion = modelBuilder.Entity<Promotion>(); promotion.ToTable("promotions"); promotion.HasKey(x => x.Id); promotion.Property(x => x.Id).HasColumnName("id"); promotion.Property(x => x.PatientId).HasColumnName("patient_id").IsRequired(); promotion.Property(x => x.Tipo).HasColumnName("tipo").HasConversion<string>().HasMaxLength(30).IsRequired(); promotion.Property(x => x.Titulo).HasColumnName("titulo").HasMaxLength(250).IsRequired(); promotion.Property(x => x.Mensaje).HasColumnName("mensaje").HasMaxLength(2000).IsRequired(); promotion.Property(x => x.FechaGenerada).HasColumnName("fecha_generada").HasColumnType("date").IsRequired(); promotion.Property(x => x.Estado).HasColumnName("estado").HasConversion<string>().HasMaxLength(30).IsRequired(); promotion.Property(x => x.CreatedAtUtc).HasColumnName("created_at_utc").IsRequired(); promotion.HasIndex(x => new { x.PatientId, x.Tipo, x.FechaGenerada }).IsUnique(); promotion.HasIndex(x => new { x.PatientId, x.Estado }); } }
